<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class mpackingmaterialmodel extends CI_Model {    function fnGetPackingMaterialInfo($VarPackingMaterial = '', $VarStatus = '', $VarId = '', $VarCompanyId = '') {        $this->db->select('id,packingmaterialname,updatedby,status,datecreated,dateupdated');        $this->db->from(KN_MASTER_PACKING_MATERIAL);        if ($VarStatus <> '') {            $this->db->where_in('status', array($VarStatus));        } else {            $this->db->where_in('status', array(1, 2));        }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarPackingMaterial <> '') {            $ArrWhere['packingmaterialname'] = $VarPackingMaterial;        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        if (@count($ArrWhere) >= 1) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheckPackingMaterial($VarPackingMaterial = '', $VarId = '', $VarCompanyId = '') {        $this->db->from(KN_MASTER_PACKING_MATERIAL);        $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarPackingMaterial <> '') {            $ArrWhere['packingmaterialname'] = $VarPackingMaterial;        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;        $this->db->where($ArrWhere);    }    function savePackingMaterialInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            $ArrCheckExist = $this->fnGetPackingMaterialInfo($ArrUpdateData['packingmaterialname'], 1, '', $ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                unset($ArrUpdateData['id']);                $this->db->insert(KN_MASTER_PACKING_MATERIAL, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This packing material already exists";            }        } else {            $ArrCheckExist = $this->fnCheckPackingMaterial($ArrUpdateData['packingmaterialname'], $VarId, $ArrUpdateData['companyid']);            if (empty($ArrCheckExist)) {                if ($this->db->update(KN_MASTER_PACKING_MATERIAL, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = "This packing material has already exist";            }        }        return $ArrResult;    }    function fnCountPackingMaterial($VarPackingMaterial = '', $VarStatus = '') {        $VarLoggedInUserId = fnGetUserLoggedInfo(1);        $ArrWhere = array();        if ($VarPackingMaterial <> '') {            $ArrWhere[] = "pn.packingmaterialname like '%" . $VarPackingMaterial . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "pn.status=" . $VarStatus;        } else {            $ArrWhere[] = "pn.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND pn.companyid = '" . $VarLoggedInUserId['companyid'] . " '";        }        $VarSqlPackingMaterial = "SELECT count(1) as trec  FROM " . KN_MASTER_PACKING_MATERIAL . " AS pn INNER JOIN " . KN_USERS . " AS u ON pn.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlPackingMaterial)->row();        return $ObjRows->trec;    }    function fnListPackingMaterial($VarPackingMaterial = '', $VarStatus = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder) {        $VarLoggedInUserId = fnGetUserLoggedInfo(1);        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array("1" => 'pn.packingmaterialname', '2' => 'pn.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'pn.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarPackingMaterial <> '') {            $ArrWhere[] = "pn.packingmaterialname like '%" . $VarPackingMaterial . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "pn.status=" . $VarStatus;        } else {            $ArrWhere[] = "pn.status in(1,2)";        }        $VarWhere = '';        if (@$ArrWhere[0] <> '') {            $VarWhere = implode(" and ", $ArrWhere) . " AND pn.companyid = '" . $VarLoggedInUserId['companyid'] . "' ";        }        $VarSqlPackingMaterial = "SELECT pn.id,pn.packingmaterialname,u.contactname,pn.datecreated,pn.dateupdated,pn.status FROM " . KN_MASTER_PACKING_MATERIAL . " AS pn INNER JOIN " . KN_USERS . " AS u ON pn.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder . " limit " . $VarLimitInfo;        $ObjResult = $this->db->query($VarSqlPackingMaterial);        return $ObjResult;    }    function fnChangeComStat($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        if ($this->db->update(KN_MASTER_PACKING_MATERIAL, array('status' => $optvalue))) {            return true;        }        return false;    }}